// ==UserScript==
// @author       Journey Over
// @exclude      *
// ==UserLibrary==
// @name         @journeyover/mydublist
// @description  MyDubList client for checking multilingual anime dub availability
// @license      MIT
// @version      1.0.1
// @homepageURL  https://github.com/StylusThemes/Userscripts
// ==/UserLibrary==
// @connect      raw.githubusercontent.com
// @grant        GM_xmlhttpRequest
// ==/UserScript==

this.MyDubList=class{constructor(){this._baseUrl='https://raw.githubusercontent.com/Joelis57/MyDubList/main/dubs/confidence';this._cache=new Map;this._pending=new Map;this._generation=0}_normalizeLanguage(language){let normalized=String(language??'english').trim().toLowerCase().replace(/[\s_]+/g,'-');const aliases={filipino:'tagalog'};normalized=aliases[normalized]||normalized;if(!/^[a-z][a-z-]*$/.test(normalized)){throw new Error(`Unsupported MyDubList language: ${language}`)}return normalized}_normalizeConfidence(confidence){let normalized=String(confidence??'normal').trim().toLowerCase().replace(/[\s_]+/g,'-');if(normalized==='veryhigh')normalized='very-high';const supported=new Set(['low','normal','high','very-high']);if(!supported.has(normalized)){throw new Error(`Unsupported MyDubList confidence: ${confidence}`)}return normalized}_normalizeMalId(id){const normalized=Number(id);if(!Number.isInteger(normalized)||normalized<=0){throw new Error(`Invalid MyAnimeList ID: ${id}`)}return normalized}_cacheKey(language,confidence){return`${language}:${confidence}`}_buildUrl(language,confidence){return`${this._baseUrl}/${confidence}/dubbed_${language}.json`}_load(language='english',confidence='normal'){const normalizedLanguage=this._normalizeLanguage(language);const normalizedConfidence=this._normalizeConfidence(confidence);const key=this._cacheKey(normalizedLanguage,normalizedConfidence);const cached=this._cache.get(key);if(cached)return Promise.resolve(cached);const pending=this._pending.get(key);if(pending)return pending;const url=this._buildUrl(normalizedLanguage,normalizedConfidence);const generation=this._generation;const request=new Promise((resolve,reject)=>{GM_xmlhttpRequest({method:'GET',url:url,timeout:15e3,onload:response=>{if(response.status!==200){reject(new Error(`MyDubList request failed with status ${response.status}`));return}try{const data=JSON.parse(response.responseText);if(!Array.isArray(data?.dubbed)){reject(new Error('Unexpected MyDubList response structure'));return}const entry={data:data,dubbed:new Set(data.dubbed.map(Number)),language:normalizedLanguage,confidence:normalizedConfidence};if(generation===this._generation)this._cache.set(key,entry);resolve(entry)}catch{reject(new Error('Failed to parse MyDubList response'))}},onerror:()=>reject(new Error('An error occurs while processing the MyDubList request')),ontimeout:()=>reject(new Error('MyDubList request times out'))})}).finally(()=>{if(this._pending.get(key)===request)this._pending.delete(key)});this._pending.set(key,request);return request}async fetch(language='english',confidence='normal'){const entry=await this._load(language,confidence);return entry.data}async isDubbed(id,language='english',confidence='normal'){const malId=this._normalizeMalId(id);const entry=await this._load(language,confidence);return entry.dubbed.has(malId)}async getStatus(id,language='english',confidence='normal'){return await this.isDubbed(id,language,confidence)?'dubbed':null}clearCache(){this._generation++;this._cache.clear();this._pending.clear()}};
